cd /testbed && patch -p1 <<'PATCH'
--- /dev/null
+++ b/tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,93 @@
+proc assert_cluster_shards_slots {id slots_by_node} {
+    set shards [R $id CLUSTER SHARDS]
+    assert_equal 3 [llength $shards]
+    foreach shard $shards {
+        assert_equal 2 [dict size $shard]
+        assert_equal 2 [llength [dict get $shard nodes]]
+        foreach node [dict get $shard nodes] {
+            assert_equal [dict get $slots_by_node [dict get $node id]] [dict get $shard slots]
+        }
+    }
+}
+
+proc cluster_shards_expected_slots {id} {
+    set slots_by_node [dict create]
+    foreach range [R $id CLUSTER SLOTS] {
+        foreach node [lrange $range 2 end] {
+            dict lappend slots_by_node [lindex $node 2] [lindex $range 0]
+            dict lappend slots_by_node [lindex $node 2] [lindex $range 1]
+        }
+    }
+    return $slots_by_node
+}
+
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set primary_id [R 0 CLUSTER MYID]
+    set replica_id [R 3 CLUSTER MYID]
+
+    test "CLUSTER SHARDS reports continuous slot ranges" {
+        set slots_by_node [cluster_shards_expected_slots 1]
+        for {set j 0} {$j < 6} {incr j} {
+            assert_cluster_shards_slots $j $slots_by_node
+        }
+    }
+
+    test "CLUSTER SHARDS reports disjoint slot ranges" {
+        set target_id [R 1 CLUSTER MYID]
+        for {set j 0} {$j < 3} {incr j} {
+            R $j CLUSTER SETSLOT 100 NODE $target_id
+        }
+        wait_for_cluster_propagation
+        set slots_by_node [cluster_shards_expected_slots 1]
+        assert_equal {0 99 101 5461} [dict get $slots_by_node $primary_id]
+        for {set j 0} {$j < 6} {incr j} {
+            assert_cluster_shards_slots $j $slots_by_node
+        }
+    }
+
+    test "CLUSTER SHARDS retains slot ranges after a primary fails" {
+        wait_for_condition 1000 50 {
+            [s -3 master_link_status] eq "up"
+        } else {
+            fail "Replica did not sync with its primary"
+        }
+
+        set paused_pid [srv 0 pid]
+        pause_process $paused_pid
+        wait_for_condition 1000 50 {
+            [cluster_has_flag [cluster_get_node_by_id 1 $replica_id] master] &&
+            [cluster_has_flag [cluster_get_node_by_id 1 $primary_id] fail] &&
+            [CI 1 cluster_state] eq "ok"
+        } else {
+            fail "Replica did not take over the failed primary's slots"
+        }
+
+        assert {[cluster_has_flag [cluster_get_node_by_id 1 $primary_id] master]}
+        assert_equal [dict get $slots_by_node $replica_id] \
+            [dict get [cluster_shards_expected_slots 1] $replica_id]
+        for {set j 1} {$j < 6} {incr j} {
+            assert_cluster_shards_slots $j $slots_by_node
+            assert_cluster_shards_slots $j $slots_by_node
+        }
+        resume_process $paused_pid
+    }
+
+    test "CLUSTER SHARDS retains slot ranges after the old primary rejoins" {
+        wait_for_condition 1000 50 {
+            [s 0 role] eq "slave"
+        } else {
+            fail "Old primary did not become a replica"
+        }
+        wait_for_cluster_propagation
+        for {set j 0} {$j < 6} {incr j} {
+            assert_cluster_shards_slots $j $slots_by_node
+        }
+    }
+}
+
+start_server {tags {external:skip cluster} overrides {cluster-enabled yes}} {
+    test "CLUSTER SHARDS reports an empty array for a slotless shard" {
+        set shards [r CLUSTER SHARDS]
+        assert_equal 1 [llength $shards]
+        assert_equal {} [dict get [lindex $shards 0] slots]
+    }
+}
PATCH
./runtest --single unit/cluster/cluster-shards

